#include <bits/stdc++.h>
using namespace std;

typedef long long ll;
const int maxn=6000;
const int inf=INT_MAX;
const ll inff=1e18;
const ll mod=1e9+7;
#define pii pair<int,int>
#define mkp make_pair
#define F first
#define S second
#define pb push_back
#define sz(v) ((int)(v).size())
#define all(v) (v).begin(),(v).end()
#define IOS ios::sync_with_stdio(0); cin.tie(0); cout.tie(0);
#define int ll
//#define endl '\n'

int n,s,t;
struct edge
{
    int to,cap,cost,rev;
};
vector<edge> G[maxn];
int dist[maxn];
int prevv[maxn],preve[maxn];
int inq[maxn];

void init(int _n,int _s,int _t)
{
    for (int i=0;i<=_n;i++) G[i].clear();
    n=_n;
    s=_s;
    t=_t;
}

void add_edge(int from,int to,int cap,int cost)
{
    G[from].pb({to,cap,cost,sz(G[to])});
    G[to].pb({from,0,-cost,sz(G[from])-1});
}

int min_cost_flow(int f)
{
    int res=0;
    while (f>0)
    {
        fill(dist,dist+n,inff);
        dist[s]=0;
        queue<int> q;
        q.push(s);
        inq[s]=1;
        while (!q.empty())
        {
            int now=q.front();
            q.pop();
            inq[now]=0;
            for (int i=0;i<sz(G[now]);i++)
            {
                edge &e=G[now][i];
                if (e.cap>0&&dist[now]+e.cost<dist[e.to])
                {
                    dist[e.to]=dist[now]+e.cost;
                    prevv[e.to]=now;
                    preve[e.to]=i;
                    if (!inq[e.to]) inq[e.to]=1,q.push(e.to);
                }
            }
        }

        if (dist[t]==inff) return -1;

        int d=f;
        for (int v=t;v!=s;v=prevv[v])
        {
            d=min(d,G[prevv[v]][preve[v]].cap);
        }
        f-=d;
        res+=d*dist[t];
        for (int v=t;v!=s;v=prevv[v])
        {
            edge &e=G[prevv[v]][preve[v]];
            e.cap-=d;
            G[v][e.rev].cap+=d;
        }
    }
    return res;
}

int N,M,K,C,D,X,Y;
int A[58];
vector<int> H[57];

int32_t main()
{
    IOS
    cin>>N>>M>>K>>C>>D;
    for (int i=1;i<=K;i++)
    {
        cin>>X;
        A[X]++;
    }
    for (int i=1;i<=M;i++)
    {
        cin>>X>>Y;
        H[X].pb(Y);
        H[Y].pb(X);
    }

    init(5103,0,5101);
    for (int i=2;i<=N;i++) add_edge(0,i,A[i],0);
    for (int i=0;i<=100;i++)
    {
        for (int l=1;l<=N;l++)
        {
            add_edge(50*i+l,50*(i+1)+l,K,0);
            for (int j:H[l])
            {
                for (int k=1;k<=K;k++)
                {
                    add_edge(50*i+l,50*(i+1)+j,1,D*(2*k-1));
                }
            }
        }
    }
    for (int i=1;i<=101;i++) add_edge(50*i+1,5101,K,C*i);
    cout<<min_cost_flow(K)<<endl;
}


